using System;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Drawing;using System.Text;using System.Xml;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 DataGridView canopies;readonly List<CanopyTakeoff> canopyResults=new List<CanopyTakeoff>();List<StockAllocation> canopyPlan=new List<StockAllocation>();List<double> canopyStock=new List<double>(CommercialBars.Lengths);FlowLayoutPanel canopySettings;ComboBox canopyFc,canopySmall,canopyLarge;
 void AddCanopyEstimates(){
  canopies=Grid(new[]{"Canopy / ledge ID","Description / opening reference","Length along wall m","Projection / width m","Thickness mm","Qty","Cover mm","Main dia mm","Main spacing mm (OR count)","Main pcs/unit (OR spacing)","Distribution dia mm","Distribution spacing mm (OR count)","Distribution pcs/unit (OR spacing)","Main wall anchorage mm","Distribution extra ends mm (total)","Also bottom mat","Concrete MPa","Grade <=12 mm","Grade >=16 mm","Concrete m3","Soffit forms m2","3-edge side forms m2","Total forms m2","Net rebar kg","Rebar BUY kg","Status"},19);
  canopies.Columns.RemoveAt(15);canopies.Columns.Insert(15,new DataGridViewCheckBoxColumn{Name="BottomMat",HeaderText="Also bottom mat",Width=125});for(int n=16;n<=18;n++)canopies.Columns[n].Visible=false;
  SetDefaults(canopies,new Dictionary<int,string>{{4,"150"},{5,"1"},{6,"25"},{7,"10"},{8,"150"},{10,"10"},{11,"150"},{14,"0"},{16,"21"},{17,"40"},{18,"60"}});
  canopies.CurrentCellDirtyStateChanged+=(s,e)=>{if(canopies.IsCurrentCellDirty&&canopies.CurrentCell is DataGridViewCheckBoxCell)canopies.CommitEdit(DataGridViewDataErrorContexts.Commit);};canopies.CellValueChanged+=(s,e)=>{if(!filling&&e.RowIndex>=0&&e.ColumnIndex==15)Recalculate();};
  AddGrid("Canopy / Ledge Estimate",canopies,"Wall-attached rectangular canopy/ledge takeoff for doors/windows. Enter L, projection, thickness, quantity and approved rebar details. Soffit + front and 2 end forms; attached wall edge/top excluded. Enter main-bar wall anchorage from the drawings. Spacing OR count per direction. Top mat standard; bottom mat optional. Cuts round UP 25mm. Not a structural design check.");
 }
 void AddCanopySettings(FlowLayoutPanel actions){canopySettings=new FlowLayoutPanel{Visible=false,AutoScroll=true,Padding=new Padding(12)};Controls.Add(canopySettings);canopyFc=SettingChoice(canopySettings,"Canopy concrete MPa",new[]{"21","28","35"});canopySmall=SettingChoice(canopySettings,"Rebar <=12 mm grade",new[]{"40","60"});canopyLarge=SettingChoice(canopySettings,"Rebar >=16 mm grade",new[]{"60","40"});Button(canopySettings,"Available stock lengths",()=>{var selected=StockLengthPicker.Choose(this,canopyStock);if(selected!=null){canopyStock=selected;Recalculate();}});Button(canopySettings,"Apply to all canopies / ledges",()=>{Commit();filling=true;try{foreach(DataGridViewRow row in canopies.Rows)if(!row.IsNewRow)CanopyMaterials(row);}finally{filling=false;}Recalculate();});Button(actions,"Canopy / Ledge Settings",()=>SettingsWorkspace.Show(this,"Canopy / Ledge",new[]{"Materials & stock lengths"},new Control[]{canopySettings}));canopies.DefaultValuesNeeded+=(s,e)=>CanopyMaterials(e.Row);canopies.RowsAdded+=(s,e)=>{if(!filling)for(int n=e.RowIndex;n<e.RowIndex+e.RowCount;n++)if(!canopies.Rows[n].IsNewRow)CanopyMaterials(canopies.Rows[n]);};}
 void CanopyMaterials(DataGridViewRow row){row.Cells[16].Value=canopyFc.Text;row.Cells[17].Value=canopySmall.Text;row.Cells[18].Value=canopyLarge.Text;}
 void RecalculateCanopies(){canopyResults.Clear();canopyPlan.Clear();if(canopies==null)return;var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in canopies.Rows){if(row.IsNewRow)continue;row.Tag=null;for(int n=19;n<=25;n++)row.Cells[n].Value="";if(Empty(row))continue;try{int gs=Count(row,17),gl=Count(row,18);var cfg=CalculationStore.Resolve(Number(row,16),gs,gs==40?275:420,gl,gl==40?275:420);var takeoff=CanopyTakeoff.Calculate(Cell(row,0),Cell(row,1),Number(row,2),Number(row,3),Number(row,4),Count(row,5),Number(row,6),new FootingBarSpec{Diameter=Count(row,7),Spacing=OptionalNumber(row,8),Count=Cell(row,9)==""?0:Count(row,9)},new FootingBarSpec{Diameter=Count(row,10),Spacing=OptionalNumber(row,11),Count=Cell(row,12)==""?0:Count(row,12)},Number(row,13),OptionalNumber(row,14),Cell(row,15)!=""&&bool.Parse(Cell(row,15)),cfg);if(!ids.Add(takeoff.Id))throw new Exception("Duplicate canopy / ledge ID.");row.Tag=takeoff;canopyResults.Add(takeoff);canopyPlan.AddRange(CommercialBars.Allocate(new[]{takeoff.Steel},cfg,canopyStock));row.Cells[19].Value=takeoff.Concrete;row.Cells[20].Value=takeoff.SoffitForms;row.Cells[21].Value=takeoff.EdgeForms;row.Cells[22].Value=takeoff.Forms;row.Cells[23].Value=takeoff.Steel.Result.Lines.Sum(l=>l.Kg);row.Cells[25].Value="Estimated";}catch(Exception ex){row.Cells[25].Value=ex.Message;errors.Add("Canopy / ledge "+Cell(row,0)+": "+ex.Message);}}}
 void UpdateCanopyPurchases(){if(canopies==null)return;foreach(DataGridViewRow row in canopies.Rows){var q=row.Tag as CanopyTakeoff;if(q==null)continue;var plan=canopyPlan.Where(a=>a.Entry==q.Steel).ToList();row.Cells[24].Value=plan.Sum(a=>a.Purchase);if(plan.Any(a=>a.Choice==null)){row.Cells[25].Value="Unresolved commercial rebar cut";errors.Add("Canopy / ledge "+q.Id+": unresolved commercial rebar cut.");}}}
 List<object[]> CanopySummary(){return new List<object[]>{new object[]{"Canopy / ledge concrete",canopyResults.Sum(q=>q.Concrete),"m3"},new object[]{"Canopy / ledge soffit formwork",canopyResults.Sum(q=>q.SoffitForms),"m2"},new object[]{"Canopy / ledge exposed side formwork",canopyResults.Sum(q=>q.EdgeForms),"m2"},new object[]{"TOTAL canopy / ledge formwork",canopyResults.Sum(q=>q.Forms),"m2"},new object[]{"Canopy / ledge rebar TO BUY (allocated)",canopyPlan.Sum(a=>a.Purchase),"kg"}};}
 void AppendCanopyReport(StringBuilder b){b.AppendLine();b.AppendLine("CANOPY / LEDGE TAKEOFF | DOORS & WINDOWS");foreach(var item in CanopySummary())b.AppendLine(item[0]+": "+Convert.ToDouble(item[1]).ToString("0.00",CultureInfo.InvariantCulture)+" "+item[2]);foreach(var q in canopyResults){b.AppendLine(q.Id+" | "+q.Description+" | concrete "+q.Fc+" MPa");b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Concrete L*B*T*qty = {0}*{1}*{2}*{3} = {4:0.000}m3",q.Length,q.Projection,q.Thickness,q.Quantity,q.Concrete));b.AppendLine("  Soffit L*B*qty = "+q.SoffitForms.ToString("0.00",CultureInfo.InvariantCulture)+"m2; sides (L+2B)*T*qty = "+q.EdgeForms.ToString("0.00",CultureInfo.InvariantCulture)+"m2.");PurchaseReports.Entry(b,canopyPlan.Where(a=>a.Entry==q.Steel).ToList(),q.Quantity,true);}b.AppendLine("No top or attached rear-wall forms, excavation, slope, haunch, structural capacity or anchorage design is inferred. Anchorage is entered from approved details; avoid double-counting any separately entered slab.");}
 void WriteCanopySettings(XmlElement root){root.SetAttribute("canopyStock",CommercialBars.FormatLengths(canopyStock));root.SetAttribute("canopyFc",canopyFc.Text);root.SetAttribute("canopySmall",canopySmall.Text);root.SetAttribute("canopyLarge",canopyLarge.Text);}
 void ReadCanopySettings(XmlElement root){canopyStock=CommercialBars.ParseLengths(root.GetAttribute("canopyStock"));foreach(var item in new[]{new{Box=canopyFc,Key="canopyFc",Fallback="21"},new{Box=canopySmall,Key="canopySmall",Fallback="40"},new{Box=canopyLarge,Key="canopyLarge",Fallback="60"}}){string value=root.HasAttribute(item.Key)?root.GetAttribute(item.Key):item.Fallback;if(!item.Box.Items.Contains(value))throw new Exception("Invalid saved canopy material setting.");item.Box.SelectedItem=value;}}
}
}
